// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

contract DCA {
    address public immutable owner;
    ISwapRouter02 public immutable router;
    address public immutable tokenIn;
    address public immutable tokenOut;
    uint24 public immutable fee;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _router, address _tokenIn, address _tokenOut, uint24 _fee) {
        owner = msg.sender;
        router = ISwapRouter02(_router);
        tokenIn = _tokenIn;
        tokenOut = _tokenOut;
        fee = _fee;
    }

    function deposit(uint256 amount) external {
        require(IERC20(tokenIn).transferFrom(msg.sender, address(this), amount), "transferFrom failed");
    }

    function buy(uint256 amountIn, uint256 minOut) external onlyOwner {
        require(IERC20(tokenIn).approve(address(router), amountIn), "approve failed");

        router.exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
    }

    function withdraw(address token, uint256 amount) external onlyOwner {
        require(IERC20(token).transfer(owner, amount), "transfer failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract Vault {
    IERC20 public immutable asset;
    uint256 public totalShares;
    uint256 public totalAssets; // internal accounting: donations don't move the price
    mapping(address => uint256) public shares;

    constructor(address _asset) { asset = IERC20(_asset); }

    function deposit(uint256 amount) external returns (uint256 s) {
        require(amount > 0, "zero amount");
        // Share price is derived from internally tracked assets, never from
        // balanceOf, so direct token transfers to the vault cannot inflate it.
        s = totalShares == 0 ? amount : (amount * totalShares) / totalAssets;
        require(s > 0, "zero shares");
        shares[msg.sender] += s;
        totalShares += s;
        totalAssets += amount;
        require(asset.transferFrom(msg.sender, address(this), amount), "transfer failed");
    }

    function withdraw(uint256 s) external returns (uint256 amount) {
        require(s > 0, "zero shares");
        amount = (s * totalAssets) / totalShares;
        shares[msg.sender] -= s;
        totalShares -= s;
        totalAssets -= amount;
        require(asset.transfer(msg.sender, amount), "transfer failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @notice Yield-bearing share vault. Yield arrives as plain transfers of the
/// asset to this contract and accrues pro-rata to existing shareholders.
///
/// Share pricing uses virtual shares/assets (ERC4626 "decimal offset" style):
/// the vault behaves as if VIRTUAL_SHARES shares backed by VIRTUAL_ASSETS
/// assets always exist. This makes the first-depositor donation/inflation
/// attack strictly unprofitable (the donation is diluted into the virtual
/// position) while direct-transfer yield still flows to real holders, since
/// the virtual position is a negligible 1-wei-scale slice of the pool.
///
/// Rounding is always down (against the caller), so a deposit/redeem round
/// trip can never extract even one wei, and the invariant
/// totalSupply <= VIRTUAL_SHARES * totalAssets guarantees every holder can
/// redeem in full, in any order, without overdrawing the vault.
contract Vault {
    IERC20 public immutable asset;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    uint256 private constant VIRTUAL_SHARES = 1e6;
    uint256 private constant VIRTUAL_ASSETS = 1;

    uint256 private _locked = 1;

    modifier nonReentrant() {
        require(_locked == 1, "REENTRANCY");
        _locked = 2;
        _;
        _locked = 1;
    }

    constructor(address _asset) {
        require(_asset != address(0), "ZERO_ASSET");
        asset = IERC20(_asset);
    }

    function totalAssets() public view returns (uint256) {
        return asset.balanceOf(address(this));
    }

    function deposit(uint256 assets) external nonReentrant returns (uint256 shares) {
        require(assets > 0, "ZERO_ASSETS");

        // Price against the balance before this deposit; measure what actually
        // arrived so fee-on-transfer tokens cannot mint unbacked shares.
        uint256 balanceBefore = asset.balanceOf(address(this));
        _safeTransferFrom(msg.sender, address(this), assets);
        uint256 received = asset.balanceOf(address(this)) - balanceBefore;

        shares = _mulDiv(
            received,
            totalSupply + VIRTUAL_SHARES,
            balanceBefore + VIRTUAL_ASSETS
        );
        require(shares > 0, "ZERO_SHARES");

        totalSupply += shares;
        balanceOf[msg.sender] += shares;
    }

    function redeem(uint256 shares) external nonReentrant returns (uint256 assets) {
        require(shares > 0, "ZERO_SHARES");
        uint256 bal = balanceOf[msg.sender];
        require(shares <= bal, "INSUFFICIENT_SHARES");

        assets = _mulDiv(
            shares,
            totalAssets() + VIRTUAL_ASSETS,
            totalSupply + VIRTUAL_SHARES
        );

        balanceOf[msg.sender] = bal - shares;
        totalSupply -= shares;

        if (assets > 0) {
            _safeTransfer(msg.sender, assets);
        }
    }

    function _safeTransfer(address to, uint256 amount) private {
        (bool ok, bytes memory data) =
            address(asset).call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FAILED");
    }

    function _safeTransferFrom(address from, address to, uint256 amount) private {
        (bool ok, bytes memory data) =
            address(asset).call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount));
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "TRANSFER_FROM_FAILED");
    }

    /// @dev floor(x * y / d) with full 512-bit intermediate precision, so
    /// share math cannot overflow-revert on large fuzzed amounts.
    function _mulDiv(uint256 x, uint256 y, uint256 d) private pure returns (uint256 result) {
        unchecked {
            uint256 prod0;
            uint256 prod1;
            assembly {
                let mm := mulmod(x, y, not(0))
                prod0 := mul(x, y)
                prod1 := sub(sub(mm, prod0), lt(mm, prod0))
            }

            if (prod1 == 0) {
                return prod0 / d;
            }

            require(d > prod1, "MULDIV_OVERFLOW");

            uint256 remainder;
            assembly {
                remainder := mulmod(x, y, d)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = d & (~d + 1);
            assembly {
                d := div(d, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }

            prod0 |= prod1 * twos;

            uint256 inverse = (3 * d) ^ 2;
            inverse *= 2 - d * inverse;
            inverse *= 2 - d * inverse;
            inverse *= 2 - d * inverse;
            inverse *= 2 - d * inverse;
            inverse *= 2 - d * inverse;
            inverse *= 2 - d * inverse;

            result = prod0 * inverse;
        }
    }
}
